#define CPU_SELFTEST_DIAG_STATUS_DIAG_FAIL_BIT_INDEX_S    8U
#define CPU_SELFTEST_DIAG_STATUS_DIAG_FAIL_BIT_INDEX_M    0xFF00U   // Error bit position

