//*************************************************************************************************
//
// The following are defines for the CLB register offsets
//
//*************************************************************************************************
#define CLB_O_COUNT_RESET           0x4U    // Counter Block RESET
#define CLB_O_COUNT_MODE_1          0x8U    // Counter Block MODE_1
#define CLB_O_COUNT_MODE_0          0xCU    // Counter Block MODE_0
#define CLB_O_COUNT_EVENT           0x10U   // Counter Block EVENT
#define CLB_O_FSM_EXTRA_IN0         0x14U   // FSM Extra EXT_IN0
#define CLB_O_FSM_EXTERNAL_IN0      0x18U   // FSM EXT_IN0
#define CLB_O_FSM_EXTERNAL_IN1      0x1CU   // FSM_EXT_IN1
#define CLB_O_FSM_EXTRA_IN1         0x20U   // FSM Extra_EXT_IN1
#define CLB_O_LUT4_IN0              0x24U   // LUT4_0/1/2 IN0 input source
#define CLB_O_LUT4_IN1              0x28U   // LUT4_0/1/2 IN1 input source
#define CLB_O_LUT4_IN2              0x2CU   // LUT4_0/1/2 IN2 input source
#define CLB_O_LUT4_IN3              0x30U   // LUT4_0/1/2 IN3 input source
#define CLB_O_FSM_LUT_FN1_0         0x38U   // LUT function for FSM Unit 1 and Unit 0
#define CLB_O_FSM_LUT_FN2           0x3CU   // LUT function for FSM Unit 2
#define CLB_O_LUT4_FN1_0            0x40U   // LUT function for LUT4 block of Unit 1 and 0
#define CLB_O_LUT4_FN2              0x44U   // LUT function for LUT4 block of Unit 2
#define CLB_O_FSM_NEXT_STATE_0      0x48U   // FSM Next state equations for Unit 0
#define CLB_O_FSM_NEXT_STATE_1      0x4CU   // FSM Next state equations for Unit 1
#define CLB_O_FSM_NEXT_STATE_2      0x50U   // FSM Next state equations for Unit 2
#define CLB_O_MISC_CONTROL          0x54U   // Static controls for Ctr,FSM
#define CLB_O_OUTPUT_LUT_0          0x58U   // Inp Sel, LUT fns for Out0
#define CLB_O_OUTPUT_LUT_1          0x5CU   // Inp Sel, LUT fns for Out1
#define CLB_O_OUTPUT_LUT_2          0x60U   // Inp Sel, LUT fns for Out2
#define CLB_O_OUTPUT_LUT_3          0x64U   // Inp Sel, LUT fns for Out3
#define CLB_O_OUTPUT_LUT_4          0x68U   // Inp Sel, LUT fns for Out4
#define CLB_O_OUTPUT_LUT_5          0x6CU   // Inp Sel, LUT fns for Out5
#define CLB_O_OUTPUT_LUT_6          0x70U   // Inp Sel, LUT fns for Out6
#define CLB_O_OUTPUT_LUT_7          0x74U   // Inp Sel, LUT fns for Out7
#define CLB_O_HLC_EVENT_SEL         0x78U   // Event Selector register for the High Level
                                            // controller
#define CLB_O_COUNT_MATCH_TAP_SEL   0x7CU   // Counter tap values for match1 and match2 outputs
#define CLB_O_OUTPUT_COND_CTRL_0    0x80U   // Output conditioning control for output 0
#define CLB_O_OUTPUT_COND_CTRL_1    0x84U   // Output conditioning control for output 1
#define CLB_O_OUTPUT_COND_CTRL_2    0x88U   // Output conditioning control for output 2
#define CLB_O_OUTPUT_COND_CTRL_3    0x8CU   // Output conditioning control for output 3
#define CLB_O_OUTPUT_COND_CTRL_4    0x90U   // Output conditioning control for output 4
#define CLB_O_OUTPUT_COND_CTRL_5    0x94U   // Output conditioning control for output 5
#define CLB_O_OUTPUT_COND_CTRL_6    0x98U   // Output conditioning control for output 6
#define CLB_O_OUTPUT_COND_CTRL_7    0x9CU   // Output conditioning control for output 7
#define CLB_O_MISC_ACCESS_CTRL      0xA0U   // Miscellaneous Access and enable control
#define CLB_O_SPI_DATA_CTRL_HI      0xA2U   // CLB to SPI buffer control High

#define CLB_O_LOAD_EN              0x0U    // Global enable & indirect load enable control, only
                                           // Global Enable Bit is LOCK protected
#define CLB_O_LOAD_ADDR            0x4U    // Indirect address
#define CLB_O_LOAD_DATA            0x8U    // Data for indirect loads
#define CLB_O_INPUT_FILTER         0xCU    // Input filter selection for both edge detection and
                                           // synchronizers
#define CLB_O_IN_MUX_SEL_0         0x10U   // Input selection to decide between Signals and GP
                                           // register
#define CLB_O_LCL_MUX_SEL_1        0x14U   // Input Mux selection for local mux
#define CLB_O_LCL_MUX_SEL_2        0x18U   // Input Mux selection for local mux
#define CLB_O_BUF_PTR              0x1CU   // PUSH and PULL pointers
#define CLB_O_GP_REG               0x20U   // General purpose register for CELL inputs
#define CLB_O_OUT_EN               0x24U   // CELL output enable register
#define CLB_O_GLBL_MUX_SEL_1       0x28U   // Global Mux select for CELL inputs
#define CLB_O_GLBL_MUX_SEL_2       0x2CU   // Global Mux select for CELL inputs
#define CLB_O_PRESCALE_CTRL        0x30U   // Prescaler register control
#define CLB_O_INTR_TAG_REG         0x40U   // Interrupt Tag register
#define CLB_O_LOCK                 0x44U   // Lock control register
#define CLB_O_HLC_INSTR_READ_PTR   0x48U   // HLC instruction read pointer
#define CLB_O_HLC_INSTR_VALUE      0x4CU   // HLC instruction read value
#define CLB_O_DBG_OUT_2            0x5CU   // Visibility for CLB inputs and final  asynchronous
                                           // outputs
#define CLB_O_DBG_R0               0x60U   // R0 of High level Controller
#define CLB_O_DBG_R1               0x64U   // R1 of High level Controller
#define CLB_O_DBG_R2               0x68U   // R2 of High level Controller
#define CLB_O_DBG_R3               0x6CU   // R3 of High level Controller
#define CLB_O_DBG_C0               0x70U   // Count of Unit 0
#define CLB_O_DBG_C1               0x74U   // Count of Unit 1
#define CLB_O_DBG_C2               0x78U   // Count of Unit 2
#define CLB_O_DBG_OUT              0x7CU   // Outputs of various units in the Cell

#define CLB_O_PUSH(i)   (0x0U + ((i) * 0x4U))    // (0 <= i < 4) CLB_PUSH FIFO Registers (from HLC)
#define CLB_O_PULL(i)   (0x80U + ((i) * 0x4U))   // (0 <= i < 4) CLB_PULL FIFO Registers (TO HLC)


