//*************************************************************************************************
//
// The following are defines for the EPG register offsets
//
//*************************************************************************************************
#define EPG_O_GCTL0                  0x0U    // EPG Global control register 0
#define EPG_O_GCTL1                  0x4U    // EPG Global control register 1
#define EPG_O_GCTL2                  0x8U    // EPG Global control register 2
#define EPG_O_GCTL3                  0xCU    // EPG Global control register 3
#define EPG_O_LOCK                   0x10U   // EPG LOCK Register
#define EPG_O_COMMIT                 0x14U   // EPG COMMIT register
#define EPG_O_GINTSTS                0x18U   // EPG Global interrupt status register.
#define EPG_O_GINTEN                 0x1CU   // EPG Global interrupt enable register.
#define EPG_O_GINTCLR                0x20U   // EPG Global interrupt clear register.
#define EPG_O_GINTFRC                0x24U   // EPG Global interrupt force register.
#define EPG_O_CLKDIV0_CTL0           0x30U   // Clock divider 0's control register 0
#define EPG_O_CLKDIV0_CLKOFFSET      0x3CU   // Clock divider 0's clock offset value
#define EPG_O_CLKDIV1_CTL0           0x48U   // Clock divider 1's control register 0
#define EPG_O_CLKDIV1_CLKOFFSET      0x54U   // Clock divider 1's clock offset value
#define EPG_O_SIGGEN0_CTL0           0x60U   // Signal generator 0's control register 0
#define EPG_O_SIGGEN0_CTL1           0x64U   // Signal generator 0's control register 1
#define EPG_O_SIGGEN0_DATA0          0x70U   // Signal generator 0's data register 0
#define EPG_O_SIGGEN0_DATA1          0x74U   // Signal generator 0's data register 1
#define EPG_O_SIGGEN0_DATA0_ACTIVE   0x78U   // Signal generator 0's data active register 0
#define EPG_O_SIGGEN0_DATA1_ACTIVE   0x7CU   // Signal generator 0's data active register 1
#define EPG_O_SIGGEN1_CTL0           0x80U   // Signal generator 1's control register 0
#define EPG_O_SIGGEN1_CTL1           0x84U   // Signal generator 1's control register 1
#define EPG_O_SIGGEN1_DATA0          0x90U   // Signal generator 1's data register 0
#define EPG_O_SIGGEN1_DATA1          0x94U   // Signal generator 1's data register 1
#define EPG_O_SIGGEN1_DATA0_ACTIVE   0x98U   // Signal generator 1's data active register 0
#define EPG_O_SIGGEN1_DATA1_ACTIVE   0x9CU   // Signal generator 1's data active register 1
#define EPG_O_REVISION               0xA0U   // IP Revision tie-off value

#define EPG_O_MXSEL0        0x0U    // EPG Mux select register 0
#define EPG_O_MXSEL1        0x4U    // EPG Mux select register 1
#define EPG_O_MXSELLOCK     0x18U   // EPG Mux select register lock
#define EPG_O_MXSELCOMMIT   0x1CU   // EPG Mux select register commit


//*************************************************************************************************
//
// The following are defines for the bit fields in the GCTL0 register
//
//*************************************************************************************************
#define EPG_GCTL0_EN            0x1U      // Enable EPG
#define EPG_GCTL0_SIGGEN0_EN    0x2U      // Signal generator enable
#define EPG_GCTL0_SIGGEN1_EN    0x4U      // Signal generator enable
#define EPG_GCTL0_EPGOUT13SEL   0x100U    // EPG output 13 Clock/signal select
#define EPG_GCTL0_EPGOUT15SEL   0x200U    // EPG output 15 Clock/signal select
#define EPG_GCTL0_EPGOUT16SEL   0x400U    // EPG output 16 Clock/signal select
#define EPG_GCTL0_EPGOUT17SEL   0x800U    // EPG output 17 Clock/signal select
#define EPG_GCTL0_EPGOUT20SEL   0x1000U   // EPG output 20 Clock/signal select
#define EPG_GCTL0_EPGOUT21SEL   0x2000U   // EPG output 21 Clock/signal select
#define EPG_GCTL0_EPGOUT22SEL   0x4000U   // EPG output 22 Clock/signal select
#define EPG_GCTL0_EPGOUT23SEL   0x8000U   // EPG output 23 Clock/signal select

//*************************************************************************************************
//
// The following are defines for the bit fields in the GCTL1 register
//
//*************************************************************************************************
#define EPG_GCTL1_SIGGEN0_CLKSEL_S   0U
#define EPG_GCTL1_SIGGEN0_CLKSEL_M   0x7U    // Clock source select of SIGGEN0
#define EPG_GCTL1_SIGGEN1_CLKSEL_S   4U
#define EPG_GCTL1_SIGGEN1_CLKSEL_M   0x70U   // Clock source select of SIGGEN1

//*************************************************************************************************
//
// The following are defines for the bit fields in the GCTL2 register
//
//*************************************************************************************************
#define EPG_GCTL2_EPGOUT0_CLKOUTSEL_S   0U
#define EPG_GCTL2_EPGOUT0_CLKOUTSEL_M   0x7U          // Selects the clock signal source of EPG
                                                      // output 0.
#define EPG_GCTL2_EPGOUT1_CLKOUTSEL_S   4U
#define EPG_GCTL2_EPGOUT1_CLKOUTSEL_M   0x70U         // Selects the clock signal source of EPG
                                                      // output 1.
#define EPG_GCTL2_EPGOUT2_CLKOUTSEL_S   8U
#define EPG_GCTL2_EPGOUT2_CLKOUTSEL_M   0x700U        // Selects the clock signal source of EPG
                                                      // output 2.
#define EPG_GCTL2_EPGOUT3_CLKOUTSEL_S   12U
#define EPG_GCTL2_EPGOUT3_CLKOUTSEL_M   0x7000U       // Selects the clock signal source of EPG
                                                      // output 3.
#define EPG_GCTL2_EPGOUT4_CLKOUTSEL_S   16U
#define EPG_GCTL2_EPGOUT4_CLKOUTSEL_M   0x70000U      // Selects the clock signal source of EPG
                                                      // output 4.
#define EPG_GCTL2_EPGOUT5_CLKOUTSEL_S   20U
#define EPG_GCTL2_EPGOUT5_CLKOUTSEL_M   0x700000U     // Selects the clock signal source of EPG
                                                      // output 5.
#define EPG_GCTL2_EPGOUT6_CLKOUTSEL_S   24U
#define EPG_GCTL2_EPGOUT6_CLKOUTSEL_M   0x7000000U    // Selects the clock signal source of EPG
                                                      // output 6.
