//
// Define for Mask Value to get the IP Revision Number.
//
#define ECAT_SS_ESCSS_IPREV_MASK (ECAT_SS_ESCSS_IPREVNUM_IP_REV_MINOR_S |\
                                  ECAT_SS_ESCSS_IPREVNUM_IP_REV_MINOR_M)

//
// Define for Mask Value to get the Raw Interrupt Mask.
//
#define ECAT_SS_ESCSS_RAW_INTERRUPT_MASK (ECAT_SS_ESCSS_INTR_RIS_SYNC0_RIS |\
                                          ECAT_SS_ESCSS_INTR_RIS_SYNC1_RIS |\
                                          ECAT_SS_ESCSS_INTR_RIS_IRQ_RIS |\
                                          ECAT_SS_ESCSS_INTR_RIS_DMA_DONE_RIS |\
                                          ECAT_SS_ESCSS_INTR_RIS_TIMEOUT_ERR_RIS |\
                                          ECAT_SS_ESCSS_INTR_RIS_MASTER_RESET_RIS)

//
// Define for Mask Value to get the Masked Interrupt Status.
//
#define ECAT_SS_ESCSS_INTERRUPT_MASK (ECAT_SS_ESCSS_INTR_MASK_SYNC0_MASK |\
                                      ECAT_SS_ESCSS_INTR_MASK_SYNC1_MASK |\
                                      ECAT_SS_ESCSS_INTR_MASK_IRQ_MASK |\
                                      ECAT_SS_ESCSS_INTR_MASK_DMA_DONE_MASK |\
                                      ECAT_SS_ESCSS_INTR_MASK_TIMEOUT_ERR_MASK |\
                                      ECAT_SS_ESCSS_INTR_MASK_MASTER_RESET_MASK)

//
// Define for Mask Value to Reset the Masked Interrupt Status.
//
#define ECAT_SS_ESCSS_RESET_INTERRUPT_MASK (ECAT_SS_ESCSS_INTR_MASK_SYNC0_MASK |\
                                            ECAT_SS_ESCSS_INTR_MASK_SYNC1_MASK |\
                                            ECAT_SS_ESCSS_INTR_MASK_IRQ_MASK |\
                                            ECAT_SS_ESCSS_INTR_MASK_DMA_DONE_MASK |\
                                            ECAT_SS_ESCSS_INTR_MASK_TIMEOUT_ERR_MASK |\
                                            ECAT_SS_ESCSS_INTR_MASK_MASTER_RESET_MASK)

//
// Define for Mask Value to Get the Masked Interrupt Status.
//
#define ECAT_SS_ESCSS_GET_INTERRUPT_MASK (ECAT_SS_ESCSS_INTR_MIS_SYNC0_MIS |\
                                          ECAT_SS_ESCSS_INTR_MIS_SYNC1_MIS |\
                                          ECAT_SS_ESCSS_INTR_MIS_IRQ_MIS |\
                                          ECAT_SS_ESCSS_INTR_MIS_DMA_DONE_MIS |\
                                          ECAT_SS_ESCSS_INTR_MIS_TIMEOUT_ERR_MIS |\
                                          ECAT_SS_ESCSS_INTR_MIS_MASTER_RESET_MIS)

//
// Define for Mask Value to Clear the Masked Interrupt Status.
//
#define ECAT_SS_ESCSS_CLEAR_INTERRUPT_MASK (ECAT_SS_ESCSS_INTR_CLR_SYNC0_CLR |\
                                            ECAT_SS_ESCSS_INTR_CLR_SYNC1_CLR |\
                                            ECAT_SS_ESCSS_INTR_CLR_IRQ_CLR |\
                                            ECAT_SS_ESCSS_INTR_CLR_DMA_DONE_CLR |\
                                            ECAT_SS_ESCSS_INTR_CLR_TIMEOUT_ERR_CLR |\
