#define FSI_O_TX_OPER_CTRL_LO      0x8U                     // Transmit operation control register
                                                            // low
#define FSI_O_TX_OPER_CTRL_HI      0xAU                     // Transmit operation control register
                                                            // high
#define FSI_O_TX_FRAME_CTRL        0xCU                     // Transmit frame control register
#define FSI_O_TX_FRAME_TAG_UDATA   0xEU                     // Transmit frame tag and user data
                                                            // register
#define FSI_O_TX_BUF_PTR_LOAD      0x10U                    // Transmit buffer pointer control load
                                                            // register
#define FSI_O_TX_BUF_PTR_STS       0x12U                    // Transmit buffer pointer control
                                                            // status register
#define FSI_O_TX_PING_CTRL         0x14U                    // Transmit ping control register
#define FSI_O_TX_PING_TAG          0x16U                    // Transmit ping tag register
#define FSI_O_TX_PING_TO_REF       0x18U                    // Transmit ping timeout counter
                                                            // reference
#define FSI_O_TX_PING_TO_CNT       0x1CU                    // Transmit ping timeout current count
#define FSI_O_TX_INT_CTRL          0x20U                    // Transmit interrupt event control
                                                            // register
#define FSI_O_TX_DMA_CTRL          0x22U                    // Transmit DMA event control register
#define FSI_O_TX_LOCK_CTRL         0x24U                    // Transmit lock control register
#define FSI_O_TX_EVT_STS           0x28U                    // Transmit event and error status flag
                                                            // register
#define FSI_O_TX_EVT_CLR           0x2CU                    // Transmit event and error clear
                                                            // register
#define FSI_O_TX_EVT_FRC           0x2EU                    // Transmit event and error flag force
                                                            // register
#define FSI_O_TX_USER_CRC          0x30U                    // Transmit user-defined CRC register
#define FSI_O_TX_ECC_DATA          0x40U                    // Transmit ECC data register
#define FSI_O_TX_ECC_VAL           0x44U                    // Transmit ECC value register
#define FSI_O_TX_DLYLINE_CTRL      0x48U                    // Transmit delay Line control register
#define FSI_O_TX_BUF_BASE(i)       (0x80U + ((i) * 0x2U))   // (0 <= i < 16) Base address for
                                                            // transmit buffer

#define FSI_O_RX_MAIN_CTRL         0x0U                     // Receive main control register
#define FSI_O_RX_OPER_CTRL         0x8U                     // Receive operation control register
#define FSI_O_RX_FRAME_INFO        0xCU                     // Receive frame control register
#define FSI_O_RX_FRAME_TAG_UDATA   0xEU                     // Receive frame tag and user data
                                                            // register
#define FSI_O_RX_DMA_CTRL          0x10U                    // Receive DMA event control register
#define FSI_O_RX_EVT_STS           0x14U                    // Receive event and error status flag
                                                            // register
#define FSI_O_RX_CRC_INFO          0x16U                    // Receive CRC info of received and
                                                            // computed CRC
#define FSI_O_RX_EVT_CLR           0x18U                    // Receive event and error clear
                                                            // register
#define FSI_O_RX_EVT_FRC           0x1AU                    // Receive event and error flag force
                                                            // register
#define FSI_O_RX_BUF_PTR_LOAD      0x1CU                    // Receive buffer pointer load register
#define FSI_O_RX_BUF_PTR_STS       0x1EU                    // Receive buffer pointer status
                                                            // register
#define FSI_O_RX_FRAME_WD_CTRL     0x20U                    // Receive frame watchdog control
                                                            // register
#define FSI_O_RX_FRAME_WD_REF      0x24U                    // Receive frame watchdog counter
                                                            // reference
#define FSI_O_RX_FRAME_WD_CNT      0x28U                    // Receive frame watchdog current count
#define FSI_O_RX_PING_WD_CTRL      0x2CU                    // Receive ping watchdog control
                                                            // register
#define FSI_O_RX_PING_TAG          0x2EU                    // Receive ping tag register
#define FSI_O_RX_PING_WD_REF       0x30U                    // Receive ping watchdog counter
                                                            // reference
#define FSI_O_RX_PING_WD_CNT       0x34U                    // Receive pingwatchdog current count
#define FSI_O_RX_INT1_CTRL         0x38U                    // Receive interrupt control register
                                                            // for RX_INT1
