                                                            // for RX_INT2
#define FSI_O_RX_LOCK_CTRL         0x3CU                    // Receive lock control register
#define FSI_O_RX_ECC_DATA          0x40U                    // Receive ECC data register
#define FSI_O_RX_ECC_VAL           0x44U                    // Receive ECC value register
#define FSI_O_RX_ECC_SEC_DATA      0x48U                    // Receive ECC corrected data register
#define FSI_O_RX_ECC_LOG           0x4CU                    // Receive ECC log and status register
#define FSI_O_RX_FRAME_TAG_CMP     0x50U                    // Receive frame tag compare register
