//*************************************************************************************************
//
// The following are defines for the SDFM register offsets
//
//*************************************************************************************************
#define SDFM_O_SDIFLG                 0x0U    // SD Interrupt Flag Register
#define SDFM_O_SDIFLGCLR              0x4U    // SD Interrupt Flag Clear Register
#define SDFM_O_SDCTL                  0x8U    // SD Control Register
#define SDFM_O_SDMFILEN               0xCU    // SD Master Filter Enable
#define SDFM_O_SDSTATUS               0xEU    // SD Status Register
#define SDFM_O_SDINTMODE              0x10U   // SD Interrupt Mode register
#define SDFM_O_SDCTLPARM1             0x20U   // Control Parameter Register for Ch1
#define SDFM_O_SDDFPARM1              0x22U   // Data Filter Parameter Register for Ch1
#define SDFM_O_SDDPARM1               0x24U   // Data Parameter Register for Ch1
#define SDFM_O_SDFLT1CMPH1            0x26U   // High-level Threshold Register for Ch1
#define SDFM_O_SDFLT1CMPL1            0x28U   // Low-level Threshold Register for Ch1
#define SDFM_O_SDCPARM1               0x2AU   // Comparator Filter Parameter Register for Ch1
#define SDFM_O_SDDATA1                0x2CU   // Data Filter Data Register (16 or 32bit) for Ch1
#define SDFM_O_SDDATFIFO1             0x30U   // Filter Data FIFO Output(32b) for Ch1
#define SDFM_O_SDCDATA1               0x34U   // Comparator Filter Data Register (16b) for Ch1
#define SDFM_O_SDFLT1CMPH2            0x36U   // Second high level threhold  for CH1
#define SDFM_O_SDFLT1CMPHZ            0x38U   // High-level (Z) Threshold Register for Ch1
#define SDFM_O_SDFIFOCTL1             0x3AU   // FIFO Control Register for Ch1
#define SDFM_O_SDSYNC1                0x3CU   // SD Filter Sync control for Ch1
#define SDFM_O_SDFLT1CMPL2            0x3EU   // Second low level threhold  for CH1
#define SDFM_O_SDCTLPARM2             0x40U   // Control Parameter Register for Ch2
#define SDFM_O_SDDFPARM2              0x42U   // Data Filter Parameter Register for Ch2
#define SDFM_O_SDDPARM2               0x44U   // Data Parameter Register for Ch2
#define SDFM_O_SDFLT2CMPH1            0x46U   // High-level Threshold Register for Ch2
#define SDFM_O_SDFLT2CMPL1            0x48U   // Low-level Threshold Register for Ch2
#define SDFM_O_SDCPARM2               0x4AU   // Comparator Filter Parameter Register for Ch2
#define SDFM_O_SDDATA2                0x4CU   // Data Filter Data Register (16 or 32bit) for Ch2
#define SDFM_O_SDDATFIFO2             0x50U   // Filter Data FIFO Output(32b) for Ch2
#define SDFM_O_SDCDATA2               0x54U   // Comparator Filter Data Register (16b) for Ch2
#define SDFM_O_SDFLT2CMPH2            0x56U   // Second high level threhold  for CH2
#define SDFM_O_SDFLT2CMPHZ            0x58U   // High-level (Z) Threshold Register for Ch2
#define SDFM_O_SDFIFOCTL2             0x5AU   // FIFO Control Register for Ch2
#define SDFM_O_SDSYNC2                0x5CU   // SD Filter Sync control for Ch2
#define SDFM_O_SDFLT2CMPL2            0x5EU   // Second low level threhold  for CH2
#define SDFM_O_SDCTLPARM3             0x60U   // Control Parameter Register for Ch3
#define SDFM_O_SDDFPARM3              0x62U   // Data Filter Parameter Register for Ch3
#define SDFM_O_SDDPARM3               0x64U   // Data Parameter Register for Ch3
#define SDFM_O_SDFLT3CMPH1            0x66U   // High-level Threshold Register for Ch3
#define SDFM_O_SDFLT3CMPL1            0x68U   // Low-level Threshold Register for Ch3
#define SDFM_O_SDCPARM3               0x6AU   // Comparator Filter Parameter Register for Ch3
#define SDFM_O_SDDATA3                0x6CU   // Data Filter Data Register (16 or 32bit) for Ch3
#define SDFM_O_SDDATFIFO3             0x70U   // Filter Data FIFO Output(32b) for Ch3
#define SDFM_O_SDCDATA3               0x74U   // Comparator Filter Data Register (16b) for Ch3
#define SDFM_O_SDFLT3CMPH2            0x76U   // Second high level threhold  for CH3
#define SDFM_O_SDFLT3CMPHZ            0x78U   // High-level (Z) Threshold Register for Ch3
#define SDFM_O_SDFIFOCTL3             0x7AU   // FIFO Control Register for Ch3
#define SDFM_O_SDSYNC3                0x7CU   // SD Filter Sync control for Ch3
#define SDFM_O_SDFLT3CMPL2            0x7EU   // Second low level threhold  for CH3
#define SDFM_O_SDCTLPARM4             0x80U   // Control Parameter Register for Ch4
#define SDFM_O_SDDFPARM4              0x82U   // Data Filter Parameter Register for Ch4
#define SDFM_O_SDDPARM4               0x84U   // Data Parameter Register for Ch4
#define SDFM_O_SDFLT4CMPH1            0x86U   // High-level Threshold Register for Ch4
#define SDFM_O_SDFLT4CMPL1            0x88U   // Low-level Threshold Register for Ch4
#define SDFM_O_SDCPARM4               0x8AU   // Comparator Filter Parameter Register for Ch4
#define SDFM_O_SDDATA4                0x8CU   // Data Filter Data Register (16 or 32bit) for Ch4
#define SDFM_O_SDDATFIFO4             0x90U   // Filter Data FIFO Output(32b) for Ch4
#define SDFM_O_SDCDATA4               0x94U   // Comparator Filter Data Register (16b) for Ch4
#define SDFM_O_SDFLT4CMPH2            0x96U   // Second high level threhold  for CH4
#define SDFM_O_SDFLT4CMPHZ            0x98U   // High-level (Z) Threshold Register for Ch4
#define SDFM_O_SDFIFOCTL4             0x9AU   // FIFO Control Register for Ch4
#define SDFM_O_SDSYNC4                0x9CU   // SD Filter Sync control for Ch4
#define SDFM_O_SDFLT4CMPL2            0x9EU   // Second low level threhold  for CH4
#define SDFM_O_SDCOMP1CTL             0xC0U   // SD Comparator event filter1 Control Register
#define SDFM_O_SDCOMP1EVT2FLTCTL      0xC2U   // COMPL/CEVT2 Digital filter1 Control Register
#define SDFM_O_SDCOMP1EVT2FLTCLKCTL   0xC4U   // COMPL/CEVT2 Digital filter1 Clock Control Register
#define SDFM_O_SDCOMP1EVT1FLTCTL      0xC6U   // COMPH/CEVT1 Digital filter1 Control Register
#define SDFM_O_SDCOMP1EVT1FLTCLKCTL   0xC8U   // COMPH/CEVT1 Digital filter1 Clock Control Register
#define SDFM_O_SDCOMP1LOCK            0xCEU   // SD  compartor event filter1 Lock Register
#define SDFM_O_SDCOMP2CTL             0xD0U   // SD Comparator event filter2 Control Register
#define SDFM_O_SDCOMP2EVT2FLTCTL      0xD2U   // COMPL/CEVT2 Digital filter2 Control Register
#define SDFM_O_SDCOMP2EVT2FLTCLKCTL   0xD4U   // COMPL/CEVT2 Digital filter2 Clock Control Register
#define SDFM_O_SDCOMP2EVT1FLTCTL      0xD6U   // COMPH/CEVT1 Digital filter2 Control Register
#define SDFM_O_SDCOMP2EVT1FLTCLKCTL   0xD8U   // COMPH/CEVT1 Digital filter2 Clock Control Register
#define SDFM_O_SDCOMP2LOCK            0xDEU   // SD  compartor event filter2 Lock Register
#define SDFM_O_SDCOMP3CTL             0xE0U   // SD Comparator event filter3 Control Register
#define SDFM_O_SDCOMP3EVT2FLTCTL      0xE2U   // COMPL/CEVT2 Digital filter3 Control Register
#define SDFM_O_SDCOMP3EVT2FLTCLKCTL   0xE4U   // COMPL/CEVT2 Digital filter3 Clock Control Register
#define SDFM_O_SDCOMP3EVT1FLTCTL      0xE6U   // COMPH/CEVT1 Digital filter3 Control Register
#define SDFM_O_SDCOMP3EVT1FLTCLKCTL   0xE8U   // COMPH/CEVT1 Digital filter3 Clock Control Register
#define SDFM_O_SDCOMP3LOCK            0xEEU   // SD  compartor event filter3 Lock Register
#define SDFM_O_SDCOMP4CTL             0xF0U   // SD Comparator event filter4 Control Register
#define SDFM_O_SDCOMP4EVT2FLTCTL      0xF2U   // COMPL/CEVT2 Digital filter4 Control Register
#define SDFM_O_SDCOMP4EVT2FLTCLKCTL   0xF4U   // COMPL/CEVT2 Digital filter4 Clock Control Register
#define SDFM_O_SDCOMP4EVT1FLTCTL      0xF6U   // COMPH/CEVT1 Digital filter4 Control Register
#define SDFM_O_SDCOMP4EVT1FLTCLKCTL   0xF8U   // COMPH/CEVT1 Digital filter4 Clock Control Register
#define SDFM_O_SDCOMP4LOCK            0xFEU   // SD  compartor event filter4 Lock Register


//*************************************************************************************************
//
// The following are defines for the bit fields in the SDIFLG register
//
//*************************************************************************************************
#define SDFM_SDIFLG_FLT1_FLG_CEVT1   0x1U          // High-level Interrupt flag for Ch1
#define SDFM_SDIFLG_FLT1_FLG_CEVT2   0x2U          // Low-level Interrupt flag for Ch1
#define SDFM_SDIFLG_FLT2_FLG_CEVT1   0x4U          // High-level Interrupt flag for Ch2
#define SDFM_SDIFLG_FLT2_FLG_CEVT2   0x8U          // Low-level Interrupt flag for Ch2
#define SDFM_SDIFLG_FLT3_FLG_CEVT1   0x10U         // High-level Interrupt flag for Ch3
#define SDFM_SDIFLG_FLT3_FLG_CEVT2   0x20U         // Low-level Interrupt flag for Ch3
#define SDFM_SDIFLG_FLT4_FLG_CEVT1   0x40U         // High-level Interrupt flag for Ch4
#define SDFM_SDIFLG_FLT4_FLG_CEVT2   0x80U         // Low-level Interrupt flag for Ch4
#define SDFM_SDIFLG_MF1              0x100U        // Modulator Failure for Filter 1
#define SDFM_SDIFLG_MF2              0x200U        // Modulator Failure for Filter 2
#define SDFM_SDIFLG_MF3              0x400U        // Modulator Failure for Filter 3
#define SDFM_SDIFLG_MF4              0x800U        // Modulator Failure for Filter 4
#define SDFM_SDIFLG_AF1              0x1000U       // Acknowledge flag for Filter 1
#define SDFM_SDIFLG_AF2              0x2000U       // Acknowledge flag for Filter 2
#define SDFM_SDIFLG_AF3              0x4000U       // Acknowledge flag for Filter 3
#define SDFM_SDIFLG_AF4              0x8000U       // Acknowledge flag for Filter 4
#define SDFM_SDIFLG_SDFFOVF1         0x10000U      // FIFO Overflow Flag for Ch1.
#define SDFM_SDIFLG_SDFFOVF2         0x20000U      // FIFO Overflow Flag for Ch2
#define SDFM_SDIFLG_SDFFOVF3         0x40000U      // FIFO Overflow Flag for Ch3
#define SDFM_SDIFLG_SDFFOVF4         0x80000U      // FIFO Overflow Flag for Ch4
#define SDFM_SDIFLG_SDFFINT1         0x100000U     // SDFIFO interrupt for Ch1
#define SDFM_SDIFLG_SDFFINT2         0x200000U     // SDFIFO interrupt for Ch2
#define SDFM_SDIFLG_SDFFINT3         0x400000U     // SDFIFO interrupt for Ch3
#define SDFM_SDIFLG_SDFFINT4         0x800000U     // SDFIFO interrupt for Ch4
#define SDFM_SDIFLG_MIF              0x80000000U   // Master Interrupt Flag

//*************************************************************************************************
//
// The following are defines for the bit fields in the SDIFLGCLR register
//
